command_executions.command:
which python python3 node npm 2>&1; echo ---; node -e '
function trywrite(path, val){
  try{
    const fd = require("fs").openSync(path, "w");
    require("fs").writeSync(fd, val);
    require("fs").closeSync(fd);
    console.log(path+": wrote "+JSON.stringify(val)+" OK");
  }catch(e){ console.log(path+": ERR "+e.code); }
}
trywrite("/sys/fs/cgroup/docker/cgroup.threads","0");
trywrite("/sys/fs/cgroup/docker/buildkit/cgroup.threads","0");
console.log("docker type:", require("fs").readFileSync("/sys/fs/cgroup/docker/cgroup.type","utf8").trim());
console.log("buildkit type:", require("fs").readFileSync("/sys/fs/cgroup/docker/buildkit/cgroup.type","utf8").trim());
'

curl -s -o /dev/null -w "health http=%{http_code}
" http://localhost:3020/api/health; curl -s http://localhost:3020/api/health; echo; echo ---; curl -s -o /dev/null -w "root http=%{http_code}
" -H "Host: urbankit.de" http://localhost:3020/; curl -s -o /dev/null -w "app host http=%{http_code}
" -H "Host: app.urbankit.de" http://localhost:3020/

echo '--- health ---'; curl -sS -o /dev/null -w 'HTTP %{http_code}
' http://localhost:3020/api/health; curl -sS http://localhost:3020/api/health | head -c 400; echo; echo '--- portal (Host urbankit.de) ---'; curl -sS -o /dev/null -w 'HTTP %{http_code} final=%{url_effective}
' -H 'Host: urbankit.de' -L http://localhost:3020/; echo '--- workspace login (Host app.urbankit.de) ---'; curl -sS -o /dev/null -w 'HTTP %{http_code} final=%{url_effective}
' -H 'Host: app.urbankit.de' -L http://localhost:3020/; echo '--- bare host ---'; curl -sS -o /dev/null -w 'HTTP %{http_code}
' http://localhost:3020/

docker exec workspace-mongo-1 mongosh --quiet --eval '
print("DBs: " + JSON.stringify(db.adminCommand({listDatabases:1}).databases.map(d=>d.name)));
var urban = db.getSiblingDB("urban_kit");
var cols = urban.getCollectionNames();
print("urban_kit collections (" + cols.length + "): " + cols.slice(0,40).join(", "));
print("users count: " + urban.users.countDocuments());
print("settings: " + JSON.stringify(urban.doc ? 1 : urban.getCollection("platform-settings").findOne({}, {_id:1})));
' 2>&1 | head -20

echo '--- mailpit UI ---'; curl -sS -o /dev/null -w 'HTTP %{http_code}
' http://localhost:8025/ ; echo '--- payload API /api/collections/users (expect 401 or 403, not 404) ---'; curl -sS -o /dev/null -w 'HTTP %{http_code}
' http://localhost:3020/api/collections/users; echo '--- portal /de/news or known portal route ---'; curl -sS -o /dev/null -w 'HTTP %{http_code}
' -H 'Host: urbankit.de' http://localhost:3020/de/bereiche 2>/dev/null; curl -sS -o /dev/null -w 'HTTP %{http_code}
' -H 'Host: app.urbankit.de' http://localhost:3020/de/projects
